<?php

namespace TranslateWP\Components;

/**
 * The TranslateWP mark for the admin menu.
 */
class BrandIcon {

	/** The 20 px mark, drawn with fills only so WordPress recolours it with the menu. */
	private const MENU_SVG_BASE64 = '';

	/** The menu icon as WordPress takes it. */
	public static function menu_icon(): string {
		return 'data:image/svg+xml;base64,' . self::MENU_SVG_BASE64;
	}
}
